#!/usr/bin/env python3
"""make_fixtures.py -- generates adversarial-suite/fixtures/ from embedded
base64 fixture bytes committed in THIS file.

Why base64-in-source instead of committing the fixture files directly:

  * Several fixtures are deliberately hostile bytes -- a UTF-8 BOM, CRLF line
    endings, an embedded NUL, an RTL override character -- and a text-mode
    write (or a text-mode diff/merge tool, or git's own newline handling)
    can silently normalize exactly the bytes the fixture exists to pin. A
    single base64 string round-trips byte-for-byte through any tool that
    treats it as opaque ASCII text, including git.
  * Committing ~120 small files invites exactly one of them to be hand-edited
    later and drift from what the test suite actually asserts. One generator
    with one source of truth cannot drift from itself.

Usage:

    python3 make_fixtures.py            # (re)generate fixtures/ next to this file
    python3 make_fixtures.py --verify   # generate into a temp dir and diff -r
                                         # it against the committed fixtures/
                                         # (exit 0 = identical, 1 = drift)

Both modes are stdlib-only: base64, hashlib, os, shutil, subprocess, sys,
tempfile.
"""
import base64
import filecmp
import os
import shutil
import subprocess
import sys
import tempfile

HERE = os.path.dirname(os.path.abspath(__file__))
FIXTURES_DIR = os.path.join(HERE, "fixtures")

