# right -- e.g. a directory passed where a file argument was expected). Both
# os.walk() and a plain `git add` drop empty directories, so these are
# recreated explicitly by generate() rather than relying on tree copy.
EMPTY_DIRS = [
    "evidence-manifest/dir_as_input",
    "reward-reconciler/dir_as_expected",
    "schema-checker/dir_as_payload"
]

def generate(dest_dir):
    """Write every fixture under dest_dir. Binary mode throughout."""
    if os.path.isdir(dest_dir):
        shutil.rmtree(dest_dir)
    os.makedirs(dest_dir, exist_ok=True)
    for relpath in sorted(FIXTURES_B64):
        full = os.path.join(dest_dir, *relpath.split("/"))
        os.makedirs(os.path.dirname(full), exist_ok=True)
        with open(full, "wb") as fh:
            fh.write(base64.b64decode(FIXTURES_B64[relpath]))
    for relpath in sorted(EMPTY_DIRS):
        full = os.path.join(dest_dir, *relpath.split("/"))
        os.makedirs(full, exist_ok=True)
    return sorted(FIXTURES_B64), sorted(EMPTY_DIRS)


def _tree_listing(root):
    """Every file and directory under root, relative, sorted, dirs suffixed
    with '/' so an empty directory is distinguishable from "nothing there"."""
    out = []
    for dirpath, dirnames, filenames in os.walk(root):
        rel = os.path.relpath(dirpath, root)
        if rel != ".":
            out.append(rel.replace(os.sep, "/") + "/")
        for name in filenames:
            full = os.path.join(dirpath, name)
            r = os.path.relpath(full, root).replace(os.sep, "/")
            out.append(r)
    return sorted(out)


def verify():
    """Regenerate into a fresh temp dir and diff -r it against the committed
    fixtures/ directory. Exercises the *committed* generator against the
    *committed* fixtures, so it catches drift from either side changing."""
    if not os.path.isdir(FIXTURES_DIR):
        print("VERIFY FAILED: %s does not exist -- run make_fixtures.py "
             "with no arguments first" % FIXTURES_DIR)
        return 1
    tmp = tempfile.mkdtemp(prefix="make_fixtures_verify_")
    try:
        generate(tmp)
        committed = _tree_listing(FIXTURES_DIR)
        fresh = _tree_listing(tmp)
        if committed != fresh:
            only_committed = sorted(set(committed) - set(fresh))
            only_fresh = sorted(set(fresh) - set(committed))
            print("VERIFY FAILED: tree listings differ")
            if only_committed:
                print("  only in committed fixtures/: %s" % only_committed)
            if only_fresh:
                print("  only in freshly generated:   %s" % only_fresh)
            return 1
        cmp_result = filecmp.dircmp(FIXTURES_DIR, tmp)
        diffs = subprocess.run(
            ["diff", "-r", FIXTURES_DIR, tmp],
            stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
        if diffs.returncode != 0:
            print("VERIFY FAILED: diff -r found byte-level differences:")
            print(diffs.stdout)
            return 1
        print("VERIFY OK: %d files + %d empty dirs, byte-identical "
             "(tree listing and diff -r both agree)"
             % (len(FIXTURES_B64), len(EMPTY_DIRS)))
        return 0
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def main(argv=None):
    argv = sys.argv[1:] if argv is None else argv
    if argv == ["--verify"]:
        return verify()
    if argv:
        sys.stderr.write("usage: make_fixtures.py [--verify]\n")
        return 2
    files, dirs = generate(FIXTURES_DIR)
    print("generated %d fixture files + %d empty directories under %s"
         % (len(files), len(dirs), os.path.relpath(FIXTURES_DIR, HERE)))
    return 0


if __name__ == "__main__":
    sys.exit(main())
